            return null;
        }

        Collection<Owner> collection = new ArrayList<Owner>( ownerDtos.size() );
        for ( OwnerDto ownerDto : ownerDtos ) {
            collection.add( toOwner( ownerDto ) );
        }

        return collection;
    }

